-- =============================================================================
-- NOVALIUS · Contenido inicial · Portfolio y plantillas
-- No se inventan clientes: el portfolio contiene la propia plataforma (proyecto
-- interno) y conceptos de laboratorio marcados con is_concept = true.
-- Las plantillas muestran NEGOCIOS FICTICIOS, señalados como demo en la web.
-- =============================================================================

insert into public.projects (slug, title, client_label, is_concept, category, summary, challenge, solution, outcome, features, stack, demo_url, accent, year, position, is_published) values
('plataforma-novalius', 'Plataforma Novalius', 'Proyecto interno', false, 'Plataforma · IA · SaaS',
 'La web que estás viendo: experiencia pública, asistente comercial con IA, motor de presupuestos, CRM, portal de clientes, juegos y un panel que controla todo sin tocar código.',
 'Necesitábamos una web que no solo presentara servicios, sino que atendiera, cualificara y gestionara clientes de principio a fin.',
 'Diseñamos una plataforma con contenido gestionable por secciones, Nova como asesora comercial, presupuestos calculados en servidor y un CRM conectado a cada conversación.',
 'Una base que evoluciona con el negocio: cada texto, servicio, tarifa o pregunta del juego se gestiona desde el panel.',
 '["Asistente Nova con IA y modo guiado", "Motor de presupuestos configurable", "CRM con estados y notas", "Portal privado de clientes", "Editor visual con versiones", "Novalius Challenge con validación en servidor"]',
 '["React", "TypeScript", "Tailwind CSS", "Three.js", "Supabase", "PostgreSQL", "Claude"]',
 '/', '#6c26e8', 2026, 0, true),

('brasa-reservas', 'Brasa & Co. · Carta y reservas', 'Proyecto conceptual', true, 'Restauración · Reservas',
 'Concepto de laboratorio para un restaurante: carta digital, reservas por franjas y una experiencia móvil pensada para decidir en segundos.',
 'Los restaurantes pierden reservas cuando el cliente tiene que llamar o buscar la carta en un PDF ilegible.',
 'Carta navegable por categorías, formulario de reserva en tres pasos y diseño editorial con fotografía a sangre.',
 'Demostración funcional disponible en la galería de plantillas.',
 '["Carta por categorías", "Reserva en tres pasos", "Horarios y ubicación", "Diseño editorial"]',
 '["React", "Tailwind CSS", "Motion"]',
 '/demo/restaurante', '#c2410c', 2026, 1, true),

('lumen-citas', 'Clínica Lumen · Citas y recepción con IA', 'Proyecto conceptual', true, 'Salud · Asistente IA',
 'Concepto para una clínica: solicitud de cita guiada, fichas de tratamientos y un asistente que resuelve dudas frecuentes antes de la visita.',
 'Las recepciones de las clínicas se saturan con llamadas repetitivas sobre horarios, precios y preparación de citas.',
 'Recorrido de cita en pasos, información clara por tratamiento y preguntas frecuentes accesibles desde cualquier página.',
 'Demostración funcional disponible en la galería de plantillas.',
 '["Solicitud de cita guiada", "Fichas de tratamientos", "Preguntas frecuentes", "Diseño accesible"]',
 '["React", "Tailwind CSS", "Claude"]',
 '/demo/clinica', '#0e7490', 2026, 2, true),

('motorline-panel', 'Motorline · Panel de órdenes de taller', 'Proyecto conceptual', true, 'Automoción · Panel',
 'Concepto de panel para un taller mecánico: cita previa online, estado del vehículo y comunicación con el cliente.',
 'Los clientes llaman constantemente para saber si su vehículo está listo.',
 'Web con cita previa y seguimiento del estado de la reparación, conectada a un panel interno.',
 'Demostración funcional de la web pública disponible en la galería de plantillas.',
 '["Cita previa", "Estado de la reparación", "Servicios y tarifas orientativas", "Panel interno"]',
 '["React", "Supabase", "PostgreSQL"]',
 '/demo/taller', '#ca8a04', 2026, 3, true);

